class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitOrLoss});
}

// Function to calculate the average profit or loss for a list of transactions
double _calculateAverageProfitOrLoss(List<Transaction> transactions) {
  double totalProfitOrLoss = 0;
  int count = 0;

  for (var transaction in transactions) {
    totalProfitOrLoss += transaction.profitOrLoss;
    count++;
  }

  return totalProfitOrLoss / count;
}

