Sure! Here's a simple JavaScript function that takes a sentence as input and returns a new sentence with the order of adjectives reversed:

```js
function reverseAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(' ');

  // Initialize variables for keeping track of adjective positions
  let firstAdjIndex = -1;
  let secondAdjIndex = -1;

  // Loop through the words to find the first and second adjectives (if present)
  for (let I = 0; I < words.length; i++) {
    const word = words[i];

    // If we find an adjective, update our adjective indices
    if (isAdjective(word)) {
      if (secondAdjIndex === -1) {
        secondAdjIndex = i;
      } else if (firstAdjIndex === -1) {
        firstAdjIndex = i;
      }
    }
  }

  // If we didn't find any adjectives, return the original sentence
  if (firstAdjIndex === -1 && secondAdjIndex === -1) {
    return sentence;
  }

  // Swap the positions of the first and second adjectives
  [words[firstAdjIndex], words[secondAdjIndex]] = [words[secondAdjIndex], words[firstAdjIndex]];

  // Join the modified array of words back into a sentence and return it
  return words.join(' ')
}

// Helper function to check if a word is an adjective
function isAdjective(word) {
  // This implementation assumes that all adjectives end in "-ly" or have the substring "ing"
  return word.endsWith("ly") || word.includes("ing");
}
```

