Here's a possible solution in Swift:

```swift
let passage = """
Their is know weigh too no if yew see something and it seems too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't no the write weigh two do it. Weather or not yew no the difference between there, their, and they're, yew can't deny that its a common mistake. But can yew correct it programmatically using Swift?
"""

// Define a dictionary mapping each homophone to its correct form
let homophones = [
    "their": "there",
    "weigh": "weight",
    "no": "know",
    "bee": "be",
    "too": "to",
    "aloud": "allowed",
    "write": "right",
    "yew": "you",
    "do": "due",
]

// Split the passage into sentences and words
var sentences = passage.components(separatedBy: .newlines)
for (i, sentence) in sentences.enumerated() {
    let words = sentence.components(separatedBy: .whitespacesAndNewlines)

    // Iterate over each word and replace homophones
    var correctedWords = [String]()
    for (j, word) in words.enumerated() {
        let replacement = homophones[word, default: word]
        correctedWords.append(replacement)
    }

    // Join the corrected words back into a sentence
    sentences[i] = correctedWords.joined(separator: " ")
}

// Join the corrected sentences back into a single string
let correctedPassage = sentences.joined(separator: .newlines)
print(correctedPassage)
```

